/* Editorial reading guides. Observations describe visible/audible evidence;
   production methods are not inferred from a finished image. */
window.CINEMA_GUIDES = {
 angles:{title:'Точка наблюдения',watch:['Сопоставь высоту камеры с глазами и корпусом персонажа. Проверь наклон горизонта отдельно от направления взгляда камеры.','Проследи, что видно с этой позиции и что скрыто: лицо, руки, пол, потолок, другие участники сцены.']},
 movement:{title:'Траектория и пространство',watch:['Следи за ближним и дальним ориентирами: их взаимное смещение помогает отличить проезд от поворота или изменения масштаба.','Сравни начало и конец движения: какую информацию камера открыла, скрыла или выделила?']},
 shotscale:{title:'Границы кадра',watch:['Посмотри, где рамка пересекает фигуру и сколько окружения остаётся вокруг неё. Название крупности зависит от этого соотношения.','Отметь, какая информация читается в этой крупности: взгляд, жест, действие целиком или расположение людей в пространстве.']},
 composition:{title:'Маршрут взгляда',watch:['Сначала найди главный зрительный акцент. Затем проверь, какие линии, световые пятна и перекрытия ведут к нему или конкурируют с ним.','В ролике посмотри, сохраняется ли рисунок при движении. Композиция одного стоп-кадра может быть только короткой фазой сцены.']},
 optics:{title:'Резкость и перспектива',watch:['Сравни передний план и фон: относительный размер предметов, перекрытия, границы резкости и форму нерезких бликов.','Отдели наблюдаемый рисунок от способа его получения. Точное стекло, диафрагму или цифровую обработку подтверждает производственный источник.']},
 lighting:{title:'Световой рисунок',watch:['Найди тень от носа, скулы или предмета: её направление показывает направление света, а край — его жёсткость.','Сравни освещённую сторону, тени и фон. Направление света, контраст и цвет — отдельные характеристики.']},
 color:{title:'Палитра и её изменения',watch:['Выдели основные цвета отдельно в коже, костюмах, декорациях, тенях и светах. Найди цветовой акцент.','В ролике сравни соседние планы: палитра сохраняется или меняется вместе с местом, временем и состоянием героя?']},
 editing:{title:'До и после склейки',watch:['Просмотри оба соседних плана целиком: что заканчивается в первом и что начинается во втором? Один кадр не показывает монтажную связь.','Отследи фазу движения, направление взгляда и звук на стыке. Проверь, какое время и пространство зритель соединяет мысленно.']},
 transitions:{title:'Устройство перехода',watch:['Найди последний различимый образ первого плана и первый образ следующего. Между ними есть наложение, перекрытие, скачок или преобразование?','Посмотри, что связывает планы: форма, движение, цвет, звук или смысл. Отдельно оцени длительность перехода.']},
 sound:{title:'Слышимое и видимое',watch:['Если у ролика доступен звук, включи его. Определи источник и то, принадлежит ли он миру сцены; источник может оставаться за кадром.','Сопоставь начало и конец звука с изображением и склейками. Немой фрагмент или фотография сами по себе звуковой приём не подтверждают.']},
 miseen:{title:'Действие внутри пространства',watch:['Отметь позиции персонажей, направление их взглядов и предметы между ними. Кто к кому приближается или от кого отделяется?','Проследи изменение расстановки от начала к концу эпизода: отношения могут измениться внутри одного плана.']},
 narrative:{title:'Подготовка и раскрытие',watch:['Раздели то, что в этот момент знает зритель, и то, что знает персонаж. Найди событие, которое меняет это соотношение.','Для вывода о приёме нужны подготовка и последствие. Короткий клип может показывать лишь одну часть этой связи.']},
 vfx:{title:'Результат и технология',watch:['Найди изменённую часть изображения и её контакт с остальным кадром: края, тени, отражения, движение и перекрытия.','Готовая сцена показывает эффект. Чтобы установить технологию, открой источник с разбором, исходными слоями или сравнением до и после.']},
 texture:{title:'Поверхность изображения',watch:['Рассмотри ровные светлые и тёмные области: где заметнее зерно, шум, царапины, мягкость или нестабильность?','В ролике проследи, меняется ли фактура от кадра к кадру. Стоп-кадр не показывает мерцание и движение зерна.']},
 rhythm:{title:'Экранное время',watch:['Сопоставь длительность жеста и количество его повторений с тем, как он выглядел бы в непрерывном действии.','Проследи интервалы между акцентами и склейками. Ускорение движения и ускорение монтажного ритма могут действовать независимо.']},
 metaphor:{title:'Образ и значение',watch:['Назови буквально показанные предметы и действия, затем найди связь, которую между ними предлагает сцена.','Проверь, поддерживается ли прочтение соседними сценами, повтором образа или поведением героя. Одна ассоциация ещё не доказывает авторский замысел.']},
 modern:{title:'Приём и задача ролика',watch:['Найди, куда направлено внимание: продукт, действие, реакция или новая информация. Отметь момент переключения между ними.','Отдели сам визуальный механизм от темпа и формата публикации: один и тот же приём может работать в рекламе и полнометражной сцене.']},
 directors:{title:'Повторяющиеся решения',watch:['Разбери пример на отдельные решения: дистанция камеры, композиция, движение, свет, монтаж, звук и игра актёров.','Сопоставь разные фильмы в галерее и источниках. Один характерный кадр иллюстрирует решение в сцене, но не описывает всё творчество режиссёра.']},
 typography:{title:'Текст как часть кадра',watch:['Отметь положение текста относительно действия: поверх изображения, на поверхности в сцене или вместо изображения.','Проследи появление, движение и исчезновение букв. Успевает ли зритель прочитать фразу и как момент чтения связан со звуком?']},
 surreal:{title:'Нарушенное правило',watch:['Найди конкретное нарушение обычной логики: масштаб, пространство, время, тело или причинность.','Проследи, как на него реагирует сцена: герои замечают невозможное или принимают его как повседневность?']},
 character:{title:'Поведение и точка зрения',watch:['Найди наблюдаемое действие: жест, паузу, взгляд, изменение позы или дистанции до другого человека.','Сопоставь реакцию героя с тем, что зрителю уже известно. Изолированное выражение лица допускает несколько прочтений.']},
 format:{title:'Устройство экрана',watch:['Сравни границы изображения, число областей и их пропорции. Чёрные поля плеера сами по себе ещё не означают авторскую смену формата.','Посмотри, какая информация появилась или исчезла после изменения рамки и как связаны одновременно показанные области.']},
 mirror:{title:'Прямое и отражённое',watch:['Определи, что камера видит напрямую, а что через отражающую поверхность. Найди границу между этими пространствами.','Проследи положение человека, отражения и камеры: совпадают ли направления движения и раскрывается ли скрытая часть сцены?']},
 documentary:{title:'Статус свидетельства',watch:['Различи наблюдение, интервью, архив, реконструкцию и иллюстрацию. Посмотри, как источник обозначен в самом фильме.','Проверь, кто сообщает информацию и что добавляет монтаж. Документальная манера изображения сама по себе не подтверждает достоверность события.']},
 television:{title:'Место в эпизоде',watch:['Отметь функцию фрагмента: начало, развитие, завершение, напоминание или переход к следующей серии.','Для приёма на уровне сезона нужны повторения и изменения между эпизодами. Один клип показывает только локальное решение.']},
 eravisual:{title:'Признаки стилизации',watch:['Раздели признаки эпохи: формат, фактура, палитра, свет, костюм, графика и характер движения.','Сравни современную стилизацию с историческим источником. Плёночное зерно или неон по отдельности не определяют эпоху и носитель.']},
 infographic:{title:'Как закодированы данные',watch:['Определи, что обозначают положение, длина, площадь, цвет и движение. Найди единицы измерения, шкалу и подписи.','Проверь сопоставимость величин и связь анимации с данными. Эффектное движение числа не объясняет происхождение самого числа.']}
};
window.CINEMA_DETAILS = {};
function D(id,a,b,effect){window.CINEMA_DETAILS[id]={...window.CINEMA_DETAILS[id],signs:[a,b],effect};}
D(1,'Горизонт и устойчивые вертикали наклонены относительно рамки.','Наклон относится ко всему изображению; наклонившаяся голова героя сама по себе его не создаёт.','Сцена теряет привычную опору по горизонтали. В контексте это может подчеркнуть сбой, угрозу или игровую условность.');
D(2,'Камера смотрит на сцену почти вертикально сверху.','Люди и предметы читаются как фигуры на плоскости; видны маршруты и взаимное расположение.','Внимание смещается от выражения лица к рисунку пространства и действия.');
D(3,'Камера находится ниже объекта и направлена вверх.','В кадре чаще видны нижние поверхности, потолок или небо за фигурой.','Фигура может казаться более монументальной; отношение к ней зависит также от крупности, дистанции и поведения.');
D(4,'Камера выше объекта и смотрит вниз под углом.','Видны верхние поверхности и больше пола вокруг фигуры.','Становится понятнее расположение героя в окружении. Уязвимость возникает из контекста, а не из высоты камеры автоматически.');
D(5,'Точка съёмки почти у земли, взгляд резко направлен вверх.','Ближайшие к объективу ноги или предметы занимают непропорционально большую часть изображения.','Обычное пространство становится непривычным по масштабу; важна близость камеры к переднему плану.');
D(6,'Плечо или затылок ближнего собеседника остаётся на переднем плане.','За ним виден другой участник; перекрытие связывает их в одном пространстве.','Зритель оказывается рядом с одним участником разговора и следит за другим через его позицию.');
D(7,'Монтаж или действие привязывает изображение к взгляду конкретного персонажа.','Кадр показывает то, на что он смотрит; обрамление глазом или видимые руки необязательны.','Доступ к событию ограничивается восприятием героя: зритель обнаруживает информацию вместе с ним.');
D(8,'Объектив примерно на уровне глаз показанного персонажа.','Камера не смотрит на него явно сверху или снизу.','Высота не создаёт дополнительного акцента на превосходстве или подчинении; отношения выстраиваются другими средствами.');
D(9,'Камера расположена примерно на уровне бедра.','Руки, оружие или предмет у пояса могут становиться главным акцентом.','Внимание легче перенести с лица на подготовку действия и предметы в руках.');
D(11,'Камера смотрит наружу из багажника, а герои заглядывают в него.','Крышка или края проёма обозначают внутреннюю точку наблюдения.','Зритель занимает скрытую, физически ограниченную позицию рядом с содержимым багажника.');
D(14,'Точка зрения связана с предметом, контейнером или внутренней нишей.','Человек обращён к этой точке и взаимодействует с предметом вокруг камеры.','Привычное действие показывается со стороны того, на что оно направлено.');
D(19,'Часть изображения перекрыта щелью, рамой или предметом рядом с камерой.','Наблюдаемое действие доступно фрагментарно, из скрытой позиции.','Ограниченный обзор делает сам акт наблюдения заметным и может создавать ощущение вторжения.');
D(21,'Размер героя остаётся примерно постоянным, пока пропорции фона заметно меняются.','Передний и дальний планы меняют соотношение: пространство визуально растягивается или сжимается.','Зритель видит пространственный сдвиг вокруг устойчивой фигуры; сцена может связать его с открытием или потерей равновесия.');
D(22,'Изображение резко проносится в сторону, часто со сплошным смазом.','До и после рывка различимы разные участки пространства.','Внимание быстро перебрасывается между объектами. Смаз может также скрыть склейку, если она действительно есть.');
D(23,'Камера перемещается вслед за действием или параллельно ему.','Герой остаётся читаемым, а окружающее пространство последовательно меняется.','Маршрут и препятствия раскрываются во времени, вместе с движущимся персонажем.');
D(24,'Точка наблюдения поднимается или опускается в пространстве, часто по дуге.','Меняются не только направление взгляда, но и видимые верхние поверхности и перекрытия.','Масштаб сцены раскрывается постепенно: от локального действия к общей расстановке или обратно.');
D(25,'Камера плавно проходит через пространство, меняет направление и высоту без выраженных шаговых толчков.','Персонаж и фон сохраняют непрерывность во время прохода.','Зритель движется внутри сцены; плавность помогает следить за действием. Тип стабилизатора по одному клипу устанавливается не всегда.');
D(26,'В композиции видны небольшие нерегулярные смещения и корректировки за действием.','Ось и горизонт могут слегка колебаться; камера реагирует на происходящее.','Может возникать ощущение физического присутствия наблюдателя. Нервозность зависит от амплитуды и контекста движения.');
D(27,'Угол обзора сужается или расширяется, объект меняет размер.','При неподвижной камере перспективное соотношение ближних и дальних объектов сохраняется.','Зритель получает более тесное или широкое выделение внутри того же направления взгляда.');
D(28,'Крупность меняется очень быстро, с резким переходом от общего к детали или обратно.','Внутри движения может сохраняться непрерывность изображения, отличающая его от простой склейки.','Быстрая смена масштаба ставит зрительный акцент на реакции, детали или открытии.');
D(29,'Камера поворачивается влево или вправо с одной позиции.','Край изображения открывает пространство сбоку; точка наблюдения не едет параллельно объектам.','Объекты соединяются одним непрерывным взглядом, либо камера следует за их перемещением.');
D(30,'Взгляд камеры поднимается или опускается поворотом на месте.','Последовательно открываются разные части объекта по высоте.','Высота и детали раскрываются дозированно; физическая точка наблюдения остаётся прежней.');
D(31,'Камера проходит дугу вокруг объекта и меняет сторону взгляда на него.','Фон смещается относительно фигуры, открываются новые поверхности.','Меняется взаимное положение героя и окружения без разрыва времени сцены.');
D(32,'Камера физически приближается к объекту; его изображение обычно растёт.','Ближние и дальние ориентиры меняют соотношение и перекрытия.','Внимание постепенно сужается, а дистанция наблюдателя до героя сокращается.');
D(33,'Камера отдаляется от объекта, вокруг него появляется больше пространства.','Окружение, скрытое в начале, становится частью композиции.','Новая информация может переосмыслить начальный крупный кадр или показать место героя в большей сцене.');
D(34,'Непрерывный обход возвращается к исходной стороне объекта после полного круга.','За удерживаемой фигурой последовательно проходят разные части окружения.','Зритель получает круговое представление о сцене, а фигура остаётся осью движения.');
D(35,'Вся камера перемещается вверх или вниз, сохраняя направление взгляда примерно постоянным.','Меняются уровень наблюдения и перекрытия объектов.','Можно перейти между уровнями действия, не превращая движение в осмотр наклоном.');
D(36,'Камера перемещается боком, а не только поворачивается.','Ближние объекты смещаются относительно фона заметнее дальних.','Пространство раскрывается за передним планом; меняются расстояния между видимыми объектами в изображении.');
D(41,'Рамка и фон сохраняют положение, пока внутри идёт действие.','Изменения композиции создаются персонажами, светом или предметами.','Зритель сам замечает изменения внутри устойчивого поля наблюдения.');
D(46,'При перемещении камеры ближние и дальние ориентиры смещаются с разной скоростью.','Один объект проходит перед другим или открывает скрытую часть фона.','Плоское изображение сильнее передаёт глубину и пространственную дистанцию между планами.');
D(85,'Небольшая деталь показана так крупно, что видны обычно незаметные фактуры.','Резкая зона часто очень узкая относительно глубины предмета.','Знакомый объект становится самостоятельным пространством для наблюдения. Масштаб на экране ещё не доказывает макроувеличение на матрице.');
D(86,'Ближний и дальний объект одновременно резки, хотя промежуточная зона может быть мягкой.','Иногда видна полоса или граница перехода между двумя зонами изображения.','Два удалённых друг от друга акцента удерживаются одновременно; зритель может заметить их связь без перевода фокуса.');
D(87,'В кадр входит широкий сектор пространства.','При близкой камере передний план заметно крупнее заднего, а дистанции кажутся растянутыми.','Окружение активно участвует в сцене. Усиленная перспектива возникает от близкой точки съёмки, а не только от фокусного расстояния.');
D(89,'В изображении выделен узкий сектор пространства.','При далёкой точке съёмки предметы разных планов кажутся близкими по размеру, фон визуально уплотняется.','Можно выделить героя из удалённого пространства и сопоставить его с плотным фоном; эффект зависит от дистанции камеры.');
D(91,'Резкость может проходить непривычной полосой или плоскостью, не параллельной обычному фронту сцены.','Узкая зона резкости в общем плане иногда создаёт впечатление миниатюры.','Меняется распределение внимания по поверхности сцены. «Игрушечный» вид можно имитировать обработкой, он не подтверждает наклон объектива.');
D(94,'Светлые точки вне резкости превращаются в диски или другие мягкие фигуры.','Форма и заполнение этих пятен различимы отдельно от резкого объекта.','Нерезкий фон получает собственный рисунок, который может поддерживать объект или отвлекать от него.');
D(99,'Несколько удалённых друг от друга планов остаются различимыми и достаточно резкими.','Действие может одновременно происходить рядом с камерой и в глубине.','Зритель может выбирать между несколькими слоями действия вместо обязательного следования за фокусом.');
D(100,'Резким остаётся ограниченный слой пространства.','Предметы перед ним и за ним заметно мягче.','Один объект выделяется среди окружения, даже если фон занимает большую часть кадра.');
D(101,'Внутри непрерывного плана резкость переходит с одного расстояния на другое.','Один объект становится читаемее в тот момент, когда другой теряет резкость.','Внимание переводится между объектами без склейки и без обязательного движения камеры.');
D(109,'Светлые участки резко соседствуют с глубокими тенями.','Свет формирует объём фигуры и оставляет часть пространства нераскрытой.','Избирательная видимость определяет, что зритель может рассмотреть и что остаётся скрытым.');
D(110,'На теневой щеке лица читается небольшой световой треугольник под глазом.','Тень от носа соединяется с тенью щеки, обрамляя этот участок.','Лицо сохраняет объём при заметном боковом контрасте; рисунок меняется с поворотом головы.');
D(111,'Большая часть изображения находится в тени, освещены отдельные зоны.','Разница между светлыми акцентами и тенями остаётся выраженной.','Видимость становится выборочной: освещённый предмет или участок лица получает дополнительный вес.');
D(112,'Тени относительно светлы, а общий контраст изображения невысок.','Большая часть важного пространства доступна взгляду без глубоких провалов.','Зритель получает открытое, хорошо читаемое поле. Светлая тональность сама по себе не задаёт комедийный жанр.');
D(113,'Светлая кромка проходит по краю фигуры со стороны источника позади неё.','Центр лица или корпуса может быть значительно темнее этой кромки.','Контур отделяет фигуру от фона и уточняет её форму.');
D(114,'В самой сцене виден действующий источник: лампа, свеча, экран или другой светильник.','Видимый источник участвует в световом рисунке или мотивирует его направление.','Освещение получает предметную причину внутри пространства; дополнительный съёмочный свет может оставаться за кадром.');
D(116,'Фигура читается преимущественно тёмным контуром на более светлом фоне.','Внутренние детали лица и одежды сильно ограничены.','Важнее становятся поза, жест и узнаваемый контур; личность может временно оставаться скрытой.');
D(118,'Граница падающей тени отчётлива и сравнительно узка.','Мелкие перепады поверхности могут давать заметные тени.','Форма и фактура читаются графично, а граница освещённого пространства становится выраженной.');
D(119,'Переход от света к тени растянут, край тени размыт.','Объём лица сохраняется, но мелкие тени менее резкие.','Переходы яркости становятся плавнее. Мягкость не означает отсутствие направления или низкий общий контраст.');
D(121,'Небольшая тень от носа расположена непосредственно под ним.','Рисунок лица близок к симметричному при фронтальном положении головы.','Центральные черты и скулы получают выраженное моделирование; высота источника влияет на читаемость глаз.');
D(122,'Одна сторона лица освещена значительно сильнее другой.','Граница света проходит примерно вдоль центральной линии лица.','Лицо разделяется на две световые области; контекст определяет, становится ли это смысловым противопоставлением.');
D(123,'Тень от носа уходит вниз и в сторону короткой петлёй.','Эта тень не соединяется с широкой тенью щеки.','Лицо получает мягкую асимметрию и объём без замкнутого треугольника на теневой щеке.');
D(124,'Тени от носа и других выступающих частей направлены вверх.','Свет достигает лица снизу, меняя привычное расположение светлых и тёмных участков.','Знакомое лицо приобретает непривычный рельеф; эффект может быть бытовым, театральным или тревожным.');
D(125,'В глазах видны небольшие отражения источника света.','Положение и форма блика меняются с направлением взгляда и взаимным положением камеры и источника.','Глаз становится более различимым, а направление взгляда — заметнее.');
D(126,'На лице, стене или полу виден рисунок полос, пятен или фигур.','Световые и теневые участки повторяют форму перекрывающего объекта или шаблона.','Свет добавляет второй композиционный слой и может обозначать невидимый за кадром предмет.');
D(136,'Небольшая область сцены выделена направленным светом сверху.','На общем плане часто различимо световое пятно; на лице заметны тени под бровями и носом.','Человек или предмет оказывается изолирован внутри ограниченной области видимости.');
D(165,'На стыке два разных изображения совпадают по форме, цвету или положению акцента.','Смена объекта остаётся заметной, несмотря на графическую непрерывность.','Склейка предлагает зрителю сопоставить разные вещи и переносит внимание через узнаваемую форму.');
D(166,'Между соседними планами заметно пропущено время при похожей композиции.','Фигура или предмет скачком меняет положение без непрерывного перехода.','Длительное действие сжимается, а сам разрыв времени остаётся видимым.');
D(168,'Монтаж поочерёдно возвращается к двум или нескольким линиям действия.','Каждый возврат продвигает свою линию; сцена может предполагать их одновременность.','Зритель удерживает несколько процессов и ожидает их встречи или смыслового сопоставления.');
D(170,'Действие развивается в продолжительном непрерывном плане.','Внимание меняется за счёт движения, мизансцены, света или резкости внутри кадра.','Экранное время приближается к непрерывному переживанию события; длительность сама по себе не задаёт его смысл.');
D(171,'Воспринимаемое движение продолжается через место предполагаемого стыка.','Переход может скрываться в темноте, смазе или полном перекрытии изображения.','Сцена сохраняет впечатление непрерывного времени и маршрута при соединении отдельных дублей.');
D(173,'Кадр лица сопоставлен с предметом или событием в другом плане.','Значение взгляда возникает из соседства изображений, даже при сдержанном выражении лица.','Зритель достраивает эмоциональную или причинную связь между изображениями. Для строгого сравнения вариантов нужен один и тот же кадр лица.');
D(174,'Монтаж чередует стороны разговора или обмена взглядами.','Положение и направление взгляда позволяют восстановить, кто напротив кого находится.','Зритель видит реплики и реакции по отдельности, сохраняя представление об общем пространстве.');
D(177,'После смены плана действие, взгляды и пространственные направления остаются согласованными.','Склейка помогает следить за событием, а не заставляет разгадывать новое расположение участников.','Несколько снятых отдельно планов воспринимаются как связное пространство и время.');
D(180,'Часть одного действия повторяется в соседнем ракурсе.','Экранная длительность момента увеличивается за счёт перекрывающихся фаз.','Движение можно рассмотреть дольше и почувствовать как более протяжённый или акцентированный момент.');
D(183,'Сначала показан взгляд персонажа за пределы кадра, затем — объект взгляда.','Направление и высота взгляда согласуются с последующим изображением.','Зритель мысленно соединяет человека и объект в общем пространстве.');
D(186,'Одна форма постепенно преобразуется в другую.','Промежуточные состояния меняют контуры и внутренние детали, а не только прозрачность.','Два объекта соединяются через превращение, которое может выражать родство, изменение или невозможность.');
D(192,'Жест начинается до склейки и продолжается после неё.','Фаза, направление и скорость действия согласованы между планами.','Внимание следует за движением и легче принимает смену точки наблюдения.');
D(193,'В переходе оба изображения некоторое время видны одновременно.','Первое постепенно теряет непрозрачность, второе её набирает.','Планы соединяются временным наложением; оно может обозначать связь, течение времени или переход между состояниями.');
D(195,'Видимая область изображения сужается или расширяется круглой маской.','Вне круга кадр закрыт, внутри него изображение сохраняется.','Внимание направляется к ограниченной области; движение маски может открывать или завершать эпизод.');
D(198,'На стыке похожих композиций части изображения плавно смещаются и деформируются.','Переход маскирует небольшое изменение позы или пропуск времени.','Разрыв можно сделать менее заметным; неудачное совмещение обнаруживает себя деформацией лица и фона.');
D(200,'Стык между разными планами проходит внутри быстрого панорамного смаза.','Направление и скорость движения по обе стороны склейки согласованы.','Два места соединяются одним ощущением рывка камеры.');
D(212,'У звука есть источник внутри мира истории, видимый или подразумеваемый.','Персонажи потенциально могут его слышать, даже если источник находится вне кадра.','Звук расширяет воспринимаемое пространство сцены за пределы изображения.');
D(213,'Музыка или другой звук адресован зрителю вне мира персонажей.','В сцене не предполагается источник, который персонажи слышат вместе со зрителем.','Появляется дополнительный авторский слой, который может поддерживать событие или спорить с ним.');
D(214,'Звук одного плана продолжается в другом либо начинается до появления своего изображения.','Звуковая граница не совпадает с визуальной склейкой.','Слух заранее связывает места и времена или удерживает предыдущую сцену поверх новой.');
D(215,'Узнаваемая музыкальная тема повторно связана с героем, местом или идеей.','При возвращении темы меняются её контекст, тембр или развитие.','Зритель узнаёт связь через повтор; один изолированный музыкальный эпизод ещё не устанавливает лейтмотив.');
D(216,'Звуковая плотность или громкость заметно уменьшается относительно окружения.','Остаются отдельные шумы, дыхание или почти полная тишина.','Привычная звуковая опора исчезает, и внимание переносится на оставшиеся сигналы.');
D(217,'Шаги, одежда и контакт с предметами синхронно сопровождают движение.','Для подтверждения фоли как способа производства нужен разбор записи или работы шумовиков.','Мелкие действия получают физическую ощутимость; по финальной дорожке нельзя надёжно отличить фоли от площадочной записи.');
D(218,'Источник слышен, но не показан в изображении.','Голос или шум позволяет предполагать присутствие кого-то за границей кадра.','Зритель мысленно достраивает невидимое пространство и может ожидать раскрытия источника.');
D(220,'Речь сопровождает изображение, не будучи видимой синхронной репликой в данном плане.','Голос может принадлежать участнику истории или внешнему рассказчику.','Между изображением и словесным объяснением появляется отношение: подтверждение, дополнение или противоречие.');
D(224,'Реплики в финальном миксе согласованы с движением губ и акустикой сцены.','Повторную студийную запись подтверждают производственные материалы, а не просто чистый голос.','Можно восстановить разборчивость или изменить реплику, сохраняя впечатление речи в пространстве сцены.');
D(229,'Тембр, громкость и доля отражений меняются вместе с точкой слушания.','Один и тот же источник звучит иначе вблизи, вдали или за препятствием.','Слух помогает почувствовать дистанцию и положение наблюдателя.');
D(233,'Музыка исходит из радио, инструмента, выступления или другого источника внутри сцены.','Герои могут реагировать на неё как на часть происходящего.','Музыка характеризует место и действие, сохраняя связь с предметным источником.');
D(251,'Повествование переходит к событию раньше текущего момента истории.','Возврат обозначается контекстом, персонажами или временными связями, а не обязательно специальным фильтром.','Прошлое меняет понимание уже увиденного или сообщает недоступную ранее причину.');
D(260,'Между сценами пропущен участок времени или действия.','Зритель восстанавливает пропуск по изменившейся ситуации и последствиям.','Рассказ сокращается до значимых моментов; сила пропуска зависит от того, что приходится достроить.');
D(516,'Внутри произведения изменяются пропорции активного изображения.','Смена рамки связана с конкретным моментом, а не с настройкой внешнего плеера.','Меняется доступное пространство и ощущение изображения; переход может маркировать время, мир или способ восприятия.');
D(541,'Текстовая карточка прерывает или разделяет изображение сцены.','Слова сообщают реплику, время, место или авторский комментарий.','Поток действия сменяется временем чтения; текст задаёт рамку следующему изображению.');
D(578,'Диалог продолжается, пока участники перемещаются через пространство.','Камера сопровождает разговор, а маршрут и встречные люди участвуют в его ритме.','Разговор одновременно сообщает информацию и показывает устройство среды и отношений.');
D(334,'Ритм кадра или монтажа соотносится с фазами дыхания.','Связь нужно проверять по движению тела и звуковой дорожке во времени.','Телесный ритм может стать мерой длительности и пауз. В этой карточке пока нет проверенного самостоятельного примера.');
D(590,'Связи и незавершённые действия продолжаются через границы нескольких эпизодов.','Повторяющиеся визуальные мотивы меняются от серии к серии.','Можно поддерживать ожидание продолжения; один кадр не доказывает такую структуру и не объясняет желание смотреть дальше.');
/* Comparisons are curated pairs, with an explanation shared by both cards. */
const compare=(a,b,text)=>{for(const [id,other] of [[a,b],[b,a]]){const d=window.CINEMA_DETAILS[id] ||= {}; (d.comparisons ||= []).push({id:other,text});}};
compare(1,3,'Голландский угол поворачивает горизонт. Нижний ракурс задаёт позицию ниже объекта; горизонт при этом может оставаться ровным.');
compare(2,4,'Вид с высоты птичьего полёта направлен почти вертикально вниз. Верхний ракурс смотрит на объект сверху под углом.');
compare(3,5,'Оба смотрят снизу, но червячий ракурс доводит точку наблюдения почти до земли.');
compare(3,4,'Нижний ракурс смотрит вверх, верхний — вниз. Сравни видимые поверхности и количество окружения, а не только предполагаемую эмоцию.');
compare(6,7,'OTS оставляет часть наблюдателя в изображении. POV привязывает сам взгляд камеры к персонажу и не требует видимого плеча.');
compare(8,12,'Уровень глаз и уровень плеча описывают высоту камеры. При одном положении тела это разные точки, даже при одинаковой крупности.');
compare(9,52,'Hip level — высота камеры; ковбойский план — граница обреза фигуры примерно у бёдер. Эти параметры могут сочетаться независимо.');
compare(11,14,'Кадр из багажника — конкретный вариант предметной точки зрения. Object POV охватывает и другие предметы, ниши и контейнеры.');
compare(19,69,'Рама внутри кадра — композиционная структура. Подглядывающий ракурс добавляет позицию скрытого наблюдателя; не каждая рама означает подглядывание.');
compare(21,27,'Зум меняет угол обзора с прежней точки. Dolly zoom сочетает изменение масштаба с движением камеры, удерживая размер героя и меняя перспективу фона.');
compare(21,32,'При обычном наезде герой обычно увеличивается. В dolly zoom этот рост компенсируется изменением фокусного расстояния, а фон продолжает меняться.');
compare(22,29,'Whip pan — резкая панорама со смазом. Обычная панорама может идти достаточно медленно, чтобы пространство читалось во время поворота.');
compare(22,200,'Whip pan — движение внутри плана. Whip transition использует похожий смаз для соединения двух отдельных планов.');
compare(23,36,'Tracking описывает сопровождение действия. Crab уточняет боковое направление проезда; сопровождение может идти также спереди или сзади.');
compare(23,25,'Tracking — отношение камеры к действию; Steadicam — способ стабилизированного движения. Сопровождение возможно с разными системами.');
compare(24,35,'Кран часто переносит камеру по дуге с изменением направления взгляда. Pedestal — преимущественно вертикальное перемещение камеры.');
compare(25,26,'В плавном стабилизированном проходе подавлены мелкие толчки. Ручная манера допускает заметные корректировки и колебания; устройство лучше проверять по источнику.');
compare(27,32,'При зуме меняется угол обзора; при наезде — точка съёмки и соотношение ближних и дальних объектов.');
compare(27,28,'Crash zoom — быстрый акцентный вариант зума. Разница прежде всего в скорости и ритмической функции.');
compare(28,179,'Crash zoom меняет крупность внутри непрерывного изображения. Осевая склейка перескакивает между двумя планами с близким направлением камеры.');
compare(29,36,'Панорама поворачивает камеру на месте. Боковой проезд переносит её и создаёт другое относительное смещение планов.');
compare(30,35,'Tilt меняет направление взгляда поворотом. Pedestal меняет высоту всей камеры; это видно по новым перекрытиям и точке наблюдения.');
compare(31,34,'Arc — часть окружности вокруг объекта. 360 orbit проходит полный круг, последовательно раскрывая все стороны.');
compare(32,33,'Наезд сокращает дистанцию и обычно сужает внимание. Отъезд увеличивает дистанцию и открывает окружение.');
compare(31,46,'Дуга описывает траекторию камеры. Параллакс — наблюдаемое взаимное смещение планов, которое возникает и на других траекториях.');
compare(41,170,'Locked-off описывает неподвижность камеры, long take — длительность непрерывного плана. Длинный план может активно двигаться.');
compare(48,49,'Экстремально крупный план выделяет фрагмент лица или детали; обычный крупный чаще сохраняет лицо как целое. Границы условны.');
compare(51,53,'Средний план обрезает фигуру в районе пояса; полный сохраняет её целиком. Меняется доступность жестов и действия ног.');
compare(54,56,'Общий план — масштаб изображения. Установочный — функция: он объясняет место и пространственную ситуацию, часто с помощью общего плана.');
compare(63,66,'Трети и золотое сечение задают разные пропорции деления рамки. Близкое положение объекта не доказывает использование одной из схем.');
compare(64,65,'Симметрия — соответствие частей относительно оси. Одноточечная перспектива — схождение линий к одной точке; она возможна и в несимметричном кадре.');
compare(68,82,'Негативное пространство оставляет большую свободную область. Тесное кадрирование уменьшает запас вокруг фигуры; оба решения зависят от границ рамки.');
compare(70,71,'Передний план — ближайший слой. Многоплановая композиция строит отношения сразу нескольких дистанций, включая среднюю и дальнюю.');
compare(85,48,'Макро относится к масштабу съёмки маленького предмета. Экстремальная крупность описывает то, сколько объекта видно на экране.');
compare(86,99,'Split diopter может оставлять резкими две раздельные зоны с переходной полосой. Deep focus даёт достаточно читаемую глубину между несколькими планами.');
compare(87,89,'Широкий и узкий угол обзора — свойства оптики. Преувеличение или уплотнение перспективы при похожей крупности связано также с выбранной дистанцией камеры.');
compare(91,100,'Tilt-shift может менять наклон плоскости резкости. Малая глубина резкости лишь ограничивает глубину читаемого слоя; цифровое размытие может имитировать оба рисунка.');
compare(94,100,'Боке — характер нерезкого изображения и бликов. Малая глубина резкости — размер резкой зоны; одинаковая глубина может давать разное боке.');
compare(99,100,'Deep focus сохраняет читаемыми несколько дистанций. Shallow focus оставляет узкий резкий слой и сильнее отделяет его от окружения.');
compare(101,103,'Rack focus переводит акцент между разными расстояниями. Follow focus удерживает выбранный движущийся объект резким.');
compare(109,111,'Кьяроскуро описывает выразительное моделирование светом и тенью. Low-key — преобладание тёмных зон и избирательного освещения; понятия часто пересекаются.');
compare(110,123,'У рембрандтовского рисунка тень носа соединяется с тенью щеки, оставляя треугольник света. У loop между этими тенями есть просвет.');
compare(110,122,'Рембрандтовский свет оставляет треугольник на теневой щеке. Split делит лицо примерно на светлую и тёмную половины.');
compare(111,112,'Low-key сохраняет большие тёмные области и выраженный контраст. High-key делает тени светлее и общую картину более открытой.');
compare(112,119,'High-key описывает тональный баланс, soft light — мягкость края тени. Мягкий источник может освещать и очень тёмную сцену.');
compare(113,116,'Контровая кромка отделяет край фигуры. Силуэт строится прежде всего на тёмной фигуре против светлого фона; оба могут сочетаться.');
compare(114,117,'Practical — видимый светящийся предмет в сцене. Мотивированный свет может исходить от скрытого съёмочного прибора, но выглядеть объяснённым окном или лампой.');
compare(118,119,'Жёсткость различают по краю падающей тени. Общая яркость и глубокий чёрный сами по себе не делают свет жёстким.');
compare(121,123,'Butterfly даёт тень под носом близко к центральной оси. Loop сдвигает её в сторону, оставляя отдельно от тени щеки.');
compare(124,136,'Подсветка снизу направляет тени вверх. Верхний прожектор даёт противоположный рисунок и часто выделяет пятно на полу.');
compare(126,138,'Гобо описывает способ формирования рисунка светотени. «Тени как рассказ» — функция этого рисунка в сцене; она не требует гобо.');
compare(165,209,'Графический match cut соединяет похожие формы. Motion match продолжает движение через стык; совпадение формы необязательно.');
compare(166,260,'Jump cut делает скачок между похожими изображениями заметным. Эллипсис — любой осмысленный пропуск времени, в том числе через совершенно разные сцены.');
compare(168,258,'Перекрёстный монтаж — способ чередовать линии. Параллельные сюжетные линии — организация истории, которая может использовать и другой монтаж.');
compare(170,171,'Длинный дубль непрерывен в съёмке. Незаметная склейка соединяет дубли так, чтобы непрерывность казалась сохранённой.');
compare(173,176,'Реакционный план показывает отклик героя. Эффект Кулешова выделяет роль соседнего изображения в том, как зритель прочитывает этот отклик.');
compare(174,183,'План-контрплан чередует стороны сцены. Eyeline match связывает направление взгляда с показанным объектом; оба могут работать вместе.');
compare(177,192,'Непрерывный монтаж согласует пространство и время сцены в целом. Склейка по движению — один из способов сделать конкретный стык связным.');
compare(180,192,'При склейке по движению жест продолжается. Overlap намеренно повторяет часть жеста и тем самым растягивает его экранную длительность.');
compare(186,193,'Морфинг изменяет форму и внутренние детали. Наплыв меняет прозрачность двух готовых изображений, не превращая одно в другое.');
compare(193,194,'Наплыв временно совмещает два плана. Затемнение или высветление уводит изображение к однотонному полю либо возвращает из него.');
compare(198,166,'Jump cut сохраняет заметный скачок. Morph cut пытается сгладить его деформацией промежуточных изображений.');
compare(212,213,'Диегетический звук принадлежит миру истории. Недиегетический адресован зрителю извне; видимость источника не определяет эту границу.');
compare(212,218,'Диегезис — принадлежность звука миру истории. Акусматичность — отсутствие видимого источника; закадровый источник может быть диегетическим.');
compare(212,233,'Диегетическая музыка — частный случай звука внутри мира сцены. Шаги, разговор и шум мотора могут принадлежать этому миру без музыки.');
compare(215,222,'Лейтмотив обычно связан с повторяющейся музыкальной темой. Звуковой мотив может строиться и на шуме, тембре или немелодическом сигнале.');
compare(217,224,'Фоли создаёт синхронные шумы действий и предметов. ADR перезаписывает речь; оба процесса относятся к постпроизводству, а не к видимости источника.');
compare(251,252,'Флешбэк переносит рассказ к более раннему событию. Флешфорвард — к более позднему относительно текущей точки истории.');
compare(254,535,'Обращение персонажа к зрителю в художественной сцене может нарушать четвёртую стену. Интервью заранее допускает обращение к камере и не требует такого нарушения.');
compare(256,266,'Предвосхищение заранее намекает на будущее. «Чеховское ружьё» связывает выделенную ранее деталь с её последующим применением или значением.');
compare(276,272,'Bookends связывает начало и конец произведения. Callback возвращает прежний элемент в любом более позднем месте, не обязательно в финале.');
compare(516,521,'Смена соотношения сторон меняет пропорции активной рамки внутри произведения. Поля letterbox и pillarbox размещают заданное изображение внутри экрана другого формата.');
compare(534,537,'Found footage подаёт материал как найденную запись внутри произведения. Архивная вставка использует ранее созданный материал; реальный архив не обязан маскироваться под находку.');
compare(536,572,'Мокьюментари строит вымышленное произведение как документальное. Документальная манера может быть локальным стилем сцены без полной конструкции мокьюментари.');
compare(578,23,'Walk-and-talk объединяет разговор и перемещение участников. Tracking описывает движение камеры, которое может сопровождать и полностью безмолвное действие.');
D(48,'Кадр занимает фрагмент лица, тела или небольшая деталь.','Объект часто выходит за рамку, а окружающее пространство почти отсутствует.','Внимание концентрируется на фактуре или микродействии: движении глаз, губ, пальцев.');
D(49,'Лицо или сопоставимый по значимости объект занимает большую часть кадра.','Окружение отступает, но выражение лица обычно читается целиком.','Зритель получает доступ к малым изменениям реакции; пространственный контекст становится менее доступным.');
D(50,'Фигура видна примерно от груди, с небольшим запасом вокруг головы.','Лицо заметно, но положение плеч и верхней части корпуса остаётся читаемым.','Реакция и часть телесного поведения остаются доступны одновременно.');
D(51,'Фигура обычно показана примерно от пояса.','В кадре читаются лицо, руки и жесты верхней части тела.','Разговор можно воспринимать вместе с действием рук и частью окружающей обстановки.');
D(52,'Нижний край кадра проходит около бёдер или середины бедра.','Руки у пояса и предметы на ремне остаются видимыми.','Жест у пояса можно показать вместе с выражением лица и положением корпуса.');
D(53,'Фигура входит в кадр целиком, от головы до ног.','Движение ног и положение тела относительно поверхности читаются без додумывания.','Действие раскрывается через тело целиком: походку, танец, физический контакт.');
D(54,'Человек занимает относительно небольшую часть пространства.','Окружение и расположение участников заметны наряду с действием.','Место становится существенной частью сцены; мелкая мимика уступает позиции и маршруту.');
D(55,'Пространство значительно преобладает над фигурой.','Люди могут читаться как небольшие точки или силуэты.','Масштаб среды, расстояния и путь важнее индивидуальной реакции.');
D(56,'План даёт ориентиры места и положения значимых объектов или людей.','Он помогает понять, где разворачивается следующее действие.','Последующие крупные планы легче связать в общее пространство. Установочный план не обязан быть первым или самым широким.');
D(57,'Отдельный план выделяет предмет или небольшое действие внутри сцены.','Деталь связана с происходящим до или после неё.','Зритель получает конкретную информацию, которая могла потеряться в более широком изображении.');
D(58,'Два персонажа одновременно присутствуют в одном плане.','Их дистанция, позы и взаимные взгляды читаются без чередования сторон.','Отношение между людьми видно в общей длительности, включая одновременные реакции.');
D(59,'Лицо обрамлено особенно тесно, часто около подбородка и лба.','Запас вокруг головы минимален, часть волос или лба может выходить за рамку.','Реакция занимает почти всё поле зрения, а свобода перемещения внутри композиции ограничена.');
D(60,'Фигура видна примерно от колен.','В кадре остаётся большая часть тела и заметный участок окружения.','Можно следить за общим положением и жестами без дистанции полноценного общего плана.');
D(61,'Из лица выделены главным образом глаза и узкая прилегающая область.','Остальная мимика и пространство исключены рамкой.','Взгляд становится самостоятельным действием, особенно в чередовании с объектом внимания.');
D(63,'Акценты расположены около линий, делящих рамку на три части.','Главный объект может занимать пересечение этих линий, оставляя пространство сбоку.','Акцент смещается от центра; свободная часть кадра может работать на направление взгляда или действие.');
D(64,'Части изображения уравновешены относительно заметной оси.','Парные формы, расстояния или фигуры поддерживают зеркальное соответствие.','Малое нарушение установленного порядка становится более заметным.');
D(65,'Линии глубины сходятся к одной выраженной точке.','Архитектура и границы пространства направляют взгляд вдоль общей оси.','Глубина получает ясное направление; положение героя относительно точки схода становится значимым.');
D(66,'Ключевые линии или акценты приближаются к делению рамки в пропорции около 1:1,618.','Спираль или сетка, наложенная после съёмки, ещё не доказывает применение схемы автором.','Пропорция может описывать распределение акцентов, но не гарантирует выразительность или красоту кадра.');
D(67,'Дороги, стены, перила, тени или другие линии сходятся к важной области.','Направление линий можно проследить от края кадра к объекту.','Взгляд получает маршрут через изображение; линия может вести и к пока пустому месту.');
D(68,'Значительная область кадра свободна от подробного действия или конкурирующих акцентов.','Фигура занимает меньшую область и явно соотнесена с этим пустым полем.','Свободное место задаёт дистанцию, ожидание появления или направление внимания.');
D(69,'Внутри внешней рамки виден второй проём: дверь, окно, арка или другая граница.','Важный объект расположен внутри этого внутреннего обрамления.','Внутри общего пространства выделяется отдельная область наблюдения.');
D(70,'Ближайший к камере предмет заметно участвует в композиции.','Он может перекрывать часть сцены, задавать масштаб или создавать границу.','Зритель ощущает позицию камеры внутри среды, а дальнее действие получает дополнительный контекст.');
D(71,'Значимые элементы расположены на ближней, средней и дальней дистанциях.','Между ними читаются перекрытия и отношения, иногда несколько действий одновременно.','Можно связать разные уровни сцены в одном изображении; резкость всех слоёв необязательна.');
D(72,'Основные направления проходят по диагонали относительно рамки.','Движение или формы поддерживают косую ось.','Изображение получает выраженное направление, которое можно продолжить действием или нарушить встречным движением.');
D(73,'Три акцента образуют читаемую треугольную структуру.','Отношения между вершинами сохраняются достаточно долго, чтобы их заметить.','Группа воспринимается как связная расстановка; вершина может выделять одного участника.');
D(74,'Важен запас над головой и перед направлением взгляда.','Эти свободные области заметно соотносятся с позой и положением персонажа.','Рамка может оставлять место для предполагаемого действия или создавать намеренное ощущение тесноты.');
D(75,'Линия дороги, тела, берега или другого элемента изгибается S-образно.','Взгляд проходит через несколько смен направления, а не по одной прямой.','Изображение можно читать как последовательный маршрут через пространство.');
D(76,'Акценты по разные стороны кадра сопоставимы по зрительному весу.','Размер, яркость, контраст и лицо человека могут уравновешивать друг друга без зеркальной формы.','Равновесие создаётся отношением разных элементов; смещение одного акцента может его нарушить.');
D(78,'Большие цветовые области формируют основное деление изображения.','Границы цвета могут совпадать с архитектурой, костюмом или освещением.','Цвет работает как композиционная масса и помогает отделять фигуру, группы или части пространства.');
D(79,'В кадре установлен повтор форм, поз, предметов или направлений.','Один элемент заметно отклоняется от этого ряда.','Выделение рождается из нарушения ожидаемого повтора; без читаемого ряда исключение теряет силу.');
D(80,'Слои глубины ослаблены, формы читаются как расположенные близко к одной плоскости.','Фронтальность, свет и перекрытия подчёркивают графический рисунок.','Кадр легче воспринимать как систему пятен, линий и ритмов, а не как маршрут в глубину.');
D(82,'Рамка оставляет мало свободного места вокруг значимого объекта.','Части фигуры или предмета могут упираться в края и выходить за них.','Контакт с рамкой усиливает заметность границ и ограничивает доступ к окружению.');
D(141,'В палитре сопоставлены сине-зелёные и тёплые оранжевые области.','Часто, но не обязательно, тёплые лица отделены от более холодного окружения.','Цветовой контраст помогает разделить фигуру и фон; он может быть создан светом, декорацией и обработкой вместе.');
D(142,'Один цвет заметно выделяется на более сдержанном или контрастном фоне.','Акцент связан с конкретным предметом, фигурой или областью.','Внимание направляется по цвету, даже если выделенный объект невелик.');
D(143,'Палитра последовательно меняется на протяжении сцены или произведения.','Изменение связано с переходами между состояниями, местами или этапами действия.','Цвет помогает почувствовать развитие, которое невозможно установить по одному отдельному кадру.');
D(144,'Изображение строится преимущественно внутри одной цветовой семьи.','Объекты разделяются также по светлоте, насыщенности и фактуре.','Палитра объединяет пространство, а редкое отклонение от неё становится сильным акцентом.');
D(145,'Цвета выглядят менее насыщенными, вплоть до почти серого изображения.','Различия яркости при этом могут оставаться очень контрастными.','Цветовые акценты ослабевают; внимание может перейти к форме, свету и фактуре.');
D(146,'Значимые цвета занимают противоположные области цветового круга.','Их столкновение заметно в костюмах, декорациях, свете или обработке.','Разные области сильнее разделяются по оттенку; эмоциональный смысл задаётся сценой.');
D(150,'Определённый цвет устойчиво связан с персонажем, предметом или идеей.','Повтор и изменение этой связи можно проследить в нескольких эпизодах.','Цвет начинает напоминать о ранее установленном значении. Единичный красный предмет сам по себе не доказывает символику.');
D(152,'Тени и светлые области имеют различное цветовое тонирование.','Разделение следует преимущественно диапазонам яркости, а не только отдельным предметам.','Тональные зоны получают дополнительное цветовое различие; точный способ коррекции уточняется по разбору.');
D(153,'В финальном кадре виден результат цветового преобразования.','Применение конкретного LUT подтверждается процессом обработки, а не узнаваемым оттенком изображения.','LUT преобразует значения цвета по заданной таблице; итоговый вид зависит и от исходного материала, и от остальных операций.');
D(155,'Дневной материал подан как ночная сцена через экспозицию, цвет и ограничение дневных ориентиров.','Способ съёмки подтверждается источником: тёмный синий кадр сам по себе не доказывает day for night.','Можно создать условность ночного пространства, сохранив особенности дневного освещения.');
D(158,'Разные части пространства устойчиво окрашены по-разному.','Герой может переходить из одной цветовой области в другую внутри плана.','Цвет разделяет места и состояния; движение человека через границу делает смену непосредственно видимой.');
D(254,'Персонаж признаёт присутствие зрителя или устройства рассказа.','Обращение нарушает установленную условность замкнутого мира сцены.','Зритель становится адресатом действия; возникает новая дистанция между героем, историей и способом её показа.');
D(256,'Ранняя деталь получает связь с более поздним событием.','После раскрытия прежний образ или реплика читаются как подготовка.','Зритель может предчувствовать событие или позже пересмотреть значение увиденного.');
D(264,'Сцена выделяет правдоподобную подсказку, которая ведёт к неверному предположению.','Позднее выясняется другая связь событий.','Зритель строит рабочую версию истории, которую последующее раскрытие заставляет изменить.');
D(265,'Зритель располагает важной информацией, которой не владеет действующий персонаж.','Обычная реплика или действие получает дополнительный смысл благодаря этому разрыву знания.','Ожидание реакции героя может создавать тревогу, комизм или сочувствие.');
D(266,'Предмет, способность или обстоятельство заранее заметно выделены.','Позднее они получают существенное применение или переосмысляются.','Подготовка и результат образуют ощутимую связь, а ранняя деталь приобретает вес задним числом.');
D(268,'Крупные части истории расположены от более позднего события к более раннему.','Каждый следующий блок раскрывает предшествующую причину уже увиденного.','Зритель движется от последствий к причинам и меняет оценку событий по мере получения прошлого.');
D(272,'Ранее показанный образ, жест или реплика возвращаются в узнаваемом виде.','Новое окружение меняет или усиливает значение повторения.','Повтор связывает отдалённые части рассказа и вознаграждает память зрителя.');
D(276,'Начало и конец произведения перекликаются композицией, действием или мотивом.','Между похожими формами заметно то, что изменилось за время истории.','Повтор обрамляет рассказ и позволяет сравнить исходное и конечное состояния.');
D(280,'Значимая часть ситуации временно скрыта рамкой, монтажом или ограниченным знанием.','В определённый момент сцена открывает недостающую информацию.','Новое изображение меняет понимание того, что зритель считал уже известным.');
D(321,'Движение развивается медленнее привычной скорости действия.','Отдельные фазы жеста становятся дольше и лучше различимы.','Момент получает дополнительное экранное время; плавность зависит от съёмки и обработки.');
D(323,'Действие останавливается на одном неизменном изображении.','Звук или рассказ могут продолжаться поверх неподвижного кадра.','Конкретное состояние выделяется из потока времени как образ для рассмотрения.');
D(324,'Скорость одного действия заметно меняется внутри фрагмента.','Переход соединяет обычное, ускоренное или замедленное движение.','Разные фазы получают разный временной вес без обязательной смены плана.');
D(325,'Медленный процесс становится видимым за короткое экранное время.','Облака, свет, строительство или потоки людей проходят большие изменения при устойчивой точке наблюдения.','Продолжительность процесса сжимается до его рисунка и направления.');
D(326,'Ускоренное течение процесса соединено с заметным перемещением точки съёмки.','Дальний ориентир может удерживаться, пока пространство быстро проходит вокруг него.','Изменение времени объединяется с маршрутом через место.');
D(337,'Последовательные фазы движения одновременно различимы как ряд изображений.','Положение тела или объекта меняется от одной фазы к следующей.','Движение становится доступным для сравнения внутри одного поля изображения.');
D(340,'Действие или часть сцены выглядит остановленной во времени.','Камера, другой персонаж или отдельный слой могут продолжать движение вокруг застывшего события.','Зритель получает доступ к моменту как к пространству; способ создания зависит от конкретной сцены.');
D(369,'Показанное вступает в противоречие с ожидаемым значением или заявлением.','Сопоставление становится понятным из контекста, а не просто из необычного вида предмета.','Зритель одновременно удерживает прямой образ и несовпадающий с ним смысл.');
compare(321,324,'Слоу-мо замедляет действие. Speed ramp изменяет скорость в пределах фрагмента и может лишь на короткое время переходить в слоу-мо.');
compare(325,326,'Таймлапс показывает ускоренный процесс. Гиперлапс добавляет выраженный маршрут камеры; небольшая панорама в таймлапсе ещё не равна такому маршруту.');
compare(323,340,'Стоп-кадр удерживает одно изображение. Временная заморозка может сохранять движение камеры или других элементов вокруг застывшего события.');
compare(141,146,'Teal & orange — конкретная пара областей палитры. Комплементарный контраст охватывает и другие противоположные оттенки.');
compare(142,150,'Цветовой акцент направляет взгляд. Цветовой символ требует установленной смысловой связи; заметный цвет не обязательно символичен.');
compare(144,145,'Монохромность ограничивает семейство оттенков. Десатурация уменьшает насыщенность; бледная сцена может оставаться многоцветной.');
compare(143,158,'Прогрессия цвета развивается во времени. Цветовые зоны разделяют пространство и могут существовать одновременно в одном кадре.');
compare(264,256,'Предвосхищение подготавливает будущее событие. Ложный след направляет ожидание к версии, которую история затем опровергает.');
compare(65,67,'Одноточечная перспектива описывает схождение пространственных линий. Ведущие линии могут быть параллельными, изогнутыми и не иметь общей точки схода.');
D(235,'Положение актёров и их маршруты меняются относительно камеры и друг друга.','Поворот, вход, выход или остановка перестраивают композицию сцены.','Отношения можно показывать действием в пространстве, без обязательной склейки или объясняющей реплики.');
D(236,'Участники действия распределены по разным дистанциям от камеры.','Событие в глубине влияет на передний план или наоборот.','Несколько уровней действия можно наблюдать одновременно и сопоставлять внутри общего времени.');
D(237,'Дистанция между людьми заметно участвует в сцене.','Приближение, отступление и разделяющие предметы меняют доступ друг к другу.','Телесная близость и границы становятся видимыми; значение дистанции зависит от ситуации и поведения.');
D(239,'Силуэт, материал, цвет и состояние одежды сообщают информацию о человеке.','Костюм сопоставляется с окружением и может меняться вместе с положением героя.','Характер и социальная роль получают зрительные признаки до прямого объяснения.');
D(281,'Два изображения наложены и видны в одном поле.','Один слой просвечивает сквозь другой; результат может быть создан при съёмке или композитингом.','Два пространства или состояния сопоставляются одновременно, а не последовательно.');
D(286,'Действие выглядит резко замедленным или почти остановленным.','Точка наблюдения при этом заметно обходит момент вокруг объекта.','Зритель рассматривает мгновение с меняющейся стороны. Конкретный способ съёмки подтверждается производственным разбором.');
D(293,'Объекты на разных расстояниях выстроены так, что кажутся взаимодействующими в одном масштабе.','Перекрытия и положение камеры поддерживают эту иллюзию.','Размер и расстояние переосмысляются через конкретную точку наблюдения; движение камеры может раскрыть подмену.');
D(295,'Передний план снят на фоне ранее полученного изображения, проецируемого сзади.','В готовой сцене важно согласование движения, перспективы и света; сам метод подтверждается источником.','Можно связать исполнителя с удалённым или опасным окружением, сохраняя съёмку переднего плана в контролируемом месте.');
D(300,'В ровных областях видна мелкая неоднородность изображения.','В движении зернистый рисунок обычно меняется от кадра к кадру.','Поверхность изображения становится ощутимой; добавленное цифровое зерно может имитировать плёночный рисунок.');
D(304,'Оттенки представлены через светлоту без цветового различия.','Разделение фигур зависит от тонов, фактур, света и контуров.','Цветовые связи уступают тональным; одинаковые по светлоте цвета могут слиться.');
D(309,'Возле ярких областей заметно свечение, выходящее за чёткую границу.','На плёночном или стилизованном материале оно может иметь окрашенный край.','Яркость получает заметный ореол. По одному изображению нельзя уверенно отличить носитель от цифровой имитации.');
D(346,'Конкретный образ предлагает прочитать его через другую идею или состояние.','Между буквальным действием и предполагаемым смыслом есть поддержанная контекстом связь.','Абстрактное переживание или отношение получает наблюдаемую форму.');
D(348,'Разные моменты повторяют сходную форму, позу, движение или композицию.','Изображения могут быть разделены многими сценами, а не соседствовать на склейке.','Повтор связывает события в памяти и приглашает сравнить изменившийся контекст.');
D(353,'Один визуальный элемент возвращается в нескольких местах произведения.','Повторы узнаваемы, но могут менять окружение, масштаб и значение.','Зритель начинает ожидать связь между появлениями; мотив становится частью памяти фильма.');
D(377,'Основная часть изображения неподвижна, а небольшая область движется.','Движение повторяется петлёй без заметного общего развития сцены.','Небольшое изменение становится особенно заметным на фоне устойчивой фотографии.');
D(383,'Фотография или изображение разделены на слои, движущиеся с разной скоростью.','Создаётся ощущение проезда, хотя исходное пространство может быть плоским.','Статичный материал получает условную глубину. Открываемые края и перекрытия выдают ограничения реконструкции.');
D(387,'Движение построено из последовательных состояний объекта.','Поза, положение или форма меняются между отдельными экспозициями; точный процесс виден в разборе съёмки.','Неподвижные предметы получают собственное действие, которое может быть физически невозможным при непрерывной съёмке.');
D(404,'Изображение состоит из отдельных плоских частей: фигур, фотографий, букв или рисунков.','Эти части перемещаются, поворачиваются и заменяются как самостоятельные элементы.','Сохраняется видимая условность собранного изображения; материал вырезок становится частью выразительности.');
D(407,'В примерах обрати внимание на фронтальные позиции, центральные оси и организованные цветовые области.','Сравни, как актёры и предметы вписаны в архитектуру кадра, а затем — как этот порядок меняется в движении.','Собранность пространства может делать небольшие жесты и отклонения особенно заметными. Это один набор решений в творчестве режиссёра.');
D(408,'В галерее сравни глубину коридоров и помещений, оси перспективы и положение фигур.','Отдели геометрический рисунок кадра от темпа сцены и поведения актёров.','Организация пространства направляет ожидание: важным становится не только человек, но и то, что находится перед ним или за ним.');
D(410,'Проследи, чей взгляд организует сцену и какая информация пока скрыта.','В примерах с наблюдением сопоставь наблюдателя, объект его взгляда и реакцию.','Доступ к информации управляет ожиданием: зритель может знать больше героя либо быть ограничен его наблюдением.');
D(411,'В галерее сопоставь знакомые бытовые детали с изменением света, цвета и пространства.','В роликах послушай фоновые шумы и паузы: тревожность может возникать раньше явного нарушения действия.','Привычная среда может постепенно терять надёжность. Отдельные шторы или цвет сами по себе ещё не составляют стиль.');
D(412,'Различай пространства и временные линии по действию и повторным возвращениям монтажа.','Сравни широкий масштаб среды с тесными кадрами участников, а не только размер экрана.','Чередование линий позволяет удерживать несколько процессов и связывать их через кульминацию.');
D(459,'Рассмотри фактуру реквизита и способы превращения вещей в фантастические образы.','Сопоставь движение объектов с монтажом; не приписывай каждому эффекту один способ производства.','Материальность предметов делает фантазию осязаемой. В конкретной сцене могут сочетаться ручные, оптические и цифровые решения.');
D(471,'Буквы занимают значительную часть экрана, иногда выходят за его границы.','Текст конкурирует по масштабу с фигурой или заменяет основное изображение.','Чтение становится главным зрительным событием; размер и обрез букв участвуют в композиции.');
D(473,'Буквы и слова перемещаются или меняют масштаб, форму и расположение во времени.','Изменения связаны с речью, музыкой или смысловыми акцентами.','Текст передаёт не только формулировку, но и темп, ударение и интонацию.');
D(481,'Информационный текст размещён преимущественно в нижней области изображения.','Он идентифицирует человека, место или другую сущность, пока основное действие остаётся видимым.','Зритель получает контекст, не прерывая наблюдение за изображением.');
D(482,'Отдельный заголовок обозначает новую часть произведения.','Номер, название или оформление разделяют историю на именованные блоки.','Переход получает структурную паузу и меняет ожидания от следующего фрагмента.');
D(484,'Слова находятся на предмете или поверхности внутри пространства сцены.','Перспектива, перекрытия и движение связывают надпись с окружением.','Информация читается как часть мира действия, а не только как внешняя подпись.');
D(496,'Элементы пространства соединены так, что противоречат обычной геометрии.','Невозможность обнаруживается в маршруте, перспективе или переходе между частями здания.','Зритель пересматривает привычную карту места; эффект особенно заметен при прослеживании движения.');
D(501,'Движение через пространство возвращает к уже пройденному месту вопреки ожидаемому маршруту.','Повторяются ориентиры, входы или действия, указывающие на замкнутость.','Продвижение перестаёт означать выход: пространство приобретает собственное правило повторения.');
D(506,'Герой отделён от группы или окружения пустотой, рамкой, светом либо резкостью.','Наблюдаемое отделение заметнее простого присутствия одного человека в кадре.','Зритель считывает положение фигуры относительно доступного ей мира; одиночество уточняется поведением и контекстом.');
D(513,'Разница размеров фигур в изображении подчёркивает их отношение.','Сравни позицию в глубине, высоту, крупность и доступное каждому пространство.','Визуальный вес распределяется неравномерно; смысл власти требует подтверждения действием сцены.');
D(526,'Отражение показывает человека, предмет или участок пространства, скрытый в прямом изображении.','Момент раскрытия зависит от движения камеры, человека или отражающей поверхности.','Зритель получает новую информацию внутри прежнего пространства, иногда раньше персонажа.');
D(531,'В одном поле одновременно видны отражённая сцена и пространство за стеклом.','Блики, прозрачность и угол взгляда меняют соотношение двух слоёв.','Два пространства могут сопоставляться без склейки; граница между ними остаётся видимой или намеренно неоднозначной.');
D(534,'Произведение подаёт изображение как запись, сделанную внутри его мира.','Носитель, автор записи или обстоятельства находки участвуют в объяснении формы.','Ограничения записи становятся частью рассказа. Шаткая камера или низкое качество сами по себе не создают found footage.');
D(535,'Человек говорит в относительно устойчивом кадре, часто обращаясь к интервьюеру или камере.','Основную информацию несут речь, лицо и паузы, окружение даёт контекст.','Зритель получает личное свидетельство или позицию; достоверность утверждений требует отдельной проверки.');
D(537,'В произведение включён ранее созданный документальный материал.','Его происхождение, дата и контекст могут быть обозначены подписями или источниками.','Рассказ получает доступ к прошлому свидетельству; значение архива меняется от отбора и соседства кадров.');
D(560,'Сцена начинается до основной заставки или титульного входа.','Она может ставить вопрос, показывать событие или завершать самостоятельную миниатюру.','Зритель вовлекается в действие раньше формального обозначения эпизода.');
D(563,'Эпизод прерывается на незавершённом действии или значимой неопределённости.','Композиция и длительность последнего кадра поддерживают открытый вопрос.','Продолжение ожидается за границей серии; сама по себе выразительная финальная картинка ещё не является клиффхэнгером.');
D(607,'Величины и связи представлены графическими элементами, которые меняются во времени.','Изменения длины, положения или формы связаны с данными и объясняются подписями.','Можно показать развитие и сравнение последовательно; шкалы и единицы нужны для правильного прочтения.');
D(608,'Место и маршрут организованы на карте.','Маркеры, границы или линия пути меняются вместе с рассказом.','События получают географическую связь и масштаб, который трудно восстановить из отдельных пейзажей.');
compare(235,237,'Блокировка описывает расстановку и движение актёров. Проксемика выделяет значение дистанций между ними; это один аспект более общей постановки.');
compare(281,193,'Двойная экспозиция удерживает наложение как состояние изображения. Наплыв использует наложение как переход от одного плана к другому.');
compare(286,340,'Bullet time — конкретный рисунок обхода замедленного или застывшего мгновения. Временная заморозка шире и не требует такого обхода.');
compare(383,46,'Параллакс — относительное смещение объектов разных дистанций. 2.5D имитирует его движением разделённых плоских слоёв.');
compare(387,404,'Покадровая анимация описывает принцип создания движения отдельными состояниями. Анимация вырезок описывает материал и устройство элементов; она может быть покадровой или цифровой.');
compare(473,493,'Кинетическая типографика охватывает движение текста в целом. Синхронизация по биту — конкретный способ привязать это движение к музыкальным акцентам.');
compare(481,484,'Lower third — внешняя информационная подпись в нижней области экрана. In-world текст принадлежит предмету или поверхности внутри сцены.');
compare(506,68,'Изоляция — отношение героя к окружению. Негативное пространство — один из способов его показать; изолировать можно также светом, резкостью или перекрытием.');
